  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;
  res.status(statusCode).json({ status: 'error', message });
};

app.use(errorHandler);
```

Missing centralized error handling — silent failures and inconsistent error responses across 40+ endpoints
## Issue

Most resource files in `backend/resources/` use try-catch blocks but many have silent failures:

- `resources/search/searchResource.js` — error just returns empty result
- `resources/leaderboard/leaderboardResource.js` — returns 500 with no detail
- Multiple resources log `console.error("Error...")` which leaks stack traces to production logs

### Why this matters

1. Silent failures make debugging impossible in production
2. `console.error` with stack traces in production logs is a security risk if logs are exposed
3. No centralized error handling — each resource implements its own error response format

### Fix

Implement a centralized error handler:
```javascript
// errors/AppError.js
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
  }
}

// middleware/errorHandler.js
const errorHandler = (err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;
  res.status(statusCode).json({ status: 'error', message });
};

app.use(errorHandler);
```

